CREATE OR REPLACE FUNCTION public.customer_quote_fingerprint(_form jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT encode(sha256(convert_to((jsonb_build_object('pickupAddress',_form->>'pickupAddress','pickupCity',_form->>'pickupCity','dropoffAddress',_form->>'dropoffAddress','dropoffCity',_form->>'dropoffCity','patientWorkspaceId',nullif(_form->>'patientWorkspaceId','')::uuid,'additionalStops',coalesce(_form->'additionalStops','[]'::jsonb),'returnDate',nullif(_form->>'returnDate','')::date,'returnPickupTime',nullif(_form->>'returnPickupTime','')::time)||CASE WHEN _form ? 'pickupState' OR _form ? 'dropoffState' OR _form ? 'pickupTimezone' OR _form ? 'dropoffTimezone' THEN jsonb_build_object('pickupState',_form->>'pickupState','dropoffState',_form->>'dropoffState','pickupZip',_form->>'pickupZip','dropoffZip',_form->>'dropoffZip','pickupCounty',_form->>'pickupCounty','dropoffCounty',_form->>'dropoffCounty','pickupTimezone',_form->>'pickupTimezone','dropoffTimezone',_form->>'dropoffTimezone') ELSE '{}'::jsonb END)::text,'UTF8')),'hex') $$;
DO $$ DECLARE body text;BEGIN SELECT pg_get_functiondef(oid) INTO body FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='get_trip_invoice_snapshot';body:=replace(body,'''history'',history)', '''history'',history,''regionalContext'',(SELECT jsonb_build_object(''pickupState'',r.pickup_state,''destinationState'',r.dropoff_state,''pickupTimezone'',r.pickup_timezone,''destinationTimezone'',r.dropoff_timezone) FROM public.ride_requests r WHERE r.id=i.request_id))');EXECUTE body;
SELECT pg_get_functiondef(oid) INTO body FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='assign_trip_resources';body:=replace(body,'PERFORM 1 FROM public.workspaces WHERE id=ws FOR UPDATE;', 'PERFORM 1 FROM public.workspaces WHERE id=ws FOR UPDATE; IF (_driver IS NOT NULL OR _vehicle IS NOT NULL) AND (t.pickup_state IS NOT NULL AND t.pickup_state<>''FL'' OR t.dropoff_state IS NOT NULL AND t.dropoff_state<>''FL'' OR t.pickup_timezone IS NOT NULL AND t.dropoff_timezone IS NOT NULL AND t.pickup_timezone<>t.dropoff_timezone) THEN RAISE EXCEPTION ''Regional scheduling requires reviewed authoritative instants; save a draft for review'';END IF;');EXECUTE body;END $$;
CREATE FUNCTION public.regional_state_eligibility(_state text,_service text) RETURNS jsonb LANGUAGE sql STABLE SET search_path=public AS $$ SELECT jsonb_build_object('state',_state,'service',_service,'configured',_state='FL','source',CASE WHEN _state='FL' THEN 'existing_florida_evaluator' ELSE 'not_configured' END,'approved',false,'automatic_matching',false) $$;
COMMENT ON FUNCTION public.regional_state_eligibility(text,text) IS 'Readiness only; Florida still requires existing evaluator, current documents, services and safety gates. All other states fail closed.';
REVOKE ALL ON FUNCTION public.regional_state_eligibility(text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.regional_state_eligibility(text,text) TO authenticated;